package com.hbm.weapon.b92;
import com.hbm.LegacyStartup;import com.hbm.registry.HbmSounds;import com.hbm.weapon.MainHandWeapon;import com.hbm.weapon.sedna.gun.GunStackData;import java.util.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.item.component.ItemAttributeModifiers;import net.minecraft.world.level.Level;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.entity.player.*;
/** Actual pre-SEDNA B92: bow-style charge/release,30tick capacitor pump, allcharge multibeam and11thcharge overload. */
public final class B92Gun extends Item implements MainHandWeapon {
 private final Random spread=new Random();public int dmgMin=16,dmgMax=28; // Original unused legacy fields; not substituted as direct beam damage.
 public B92Gun(){super(new Properties().stacksTo(1).rarity(Rarity.UNCOMMON).attributes(ItemAttributeModifiers.builder().add(Attributes.ATTACK_DAMAGE,new AttributeModifier(BASE_ATTACK_DAMAGE_ID,3.5,AttributeModifier.Operation.ADD_VALUE),EquipmentSlotGroup.MAINHAND).build()));}
 @Override public int getUseDuration(ItemStack stack,LivingEntity entity){return 72000;}@Override public UseAnim getUseAnimation(ItemStack stack){return UseAnim.BOW;}@Override public int getEnchantmentValue(){return 1;}
 @Override public InteractionResultHolder<ItemStack> use(Level level,Player player,InteractionHand hand){var stack=player.getItemInHand(hand);if(hand!=InteractionHand.MAIN_HAND)return InteractionResultHolder.fail(stack);if(!player.isShiftKeyDown()&&energy(stack)>0){NeoForge.EVENT_BUS.post(new ArrowNockEvent(player,stack,hand,level,true));if(animation(stack)==0)player.startUsingItem(hand);}else if(animation(stack)==0)setAnimation(stack,1);return InteractionResultHolder.consume(stack);}
 @Override public void releaseUsing(ItemStack stack,Level level,LivingEntity consumer,int timeLeft){if(!(consumer instanceof Player player)||player.isShiftKeyDown())return;int charge=getUseDuration(stack,player)-timeLeft;var event=new ArrowLooseEvent(player,stack,level,charge,true);NeoForge.EVENT_BUS.post(event);charge=event.getCharge();if(charge<10)return;
  if(!level.isClientSide)for(int i=0;i<energy(stack);i++){var beam=new EntityB92Beam(level,player,3);float divergence=Math.min(i*.2F,1);if(i>0)beam.setDeltaMovement(beam.getDeltaMovement().add(spread.nextGaussian()*divergence,spread.nextGaussian()*divergence,spread.nextGaussian()*divergence));stack.hurtAndBreak(1,player,EquipmentSlot.MAINHAND);level.addFreshEntity(beam);}
  sound(level,player,"weapon.sparkShoot",5,1);setAnimation(stack,1);setEnergy(stack,0);
 }
 @Override public void inventoryTick(ItemStack stack,Level level,Entity entity,int slot,boolean selected){int animation=animation(stack);if(animation<=0)return;setAnimation(stack,animation<30?animation+1:0);if(animation==15){sound(level,entity,"weapon.b92Reload",2,.9F);setEnergy(stack,energy(stack)+1);if(energy(stack)>10){setEnergy(stack,0);B92Blast.explode(level,entity.getX(),entity.getY(),entity.getZ(),50);}}}
 private static void sound(Level level,Entity entity,String sound,float volume,float pitch){if(level.isClientSide)level.playLocalSound(entity.getX(),entity.getY(),entity.getZ(),HbmSounds.get(sound),entity.getSoundSource(),volume,pitch,false);else level.playSound(null,entity.getX(),entity.getY(),entity.getZ(),HbmSounds.get(sound),entity.getSoundSource(),volume,pitch);}
 public static int animation(ItemStack stack){return GunStackData.data(stack).getInt("animation");}public static int energy(ItemStack stack){return GunStackData.data(stack).getInt("energy");}public static void setAnimation(ItemStack stack,int value){GunStackData.update(stack,data->data.putInt("animation",value));}public static void setEnergy(ItemStack stack,int value){GunStackData.update(stack,data->data.putInt("energy",value));}
 public static float rotation(ItemStack stack){float radians=.0174533F;radians*=7.5F;int i=animation(stack);if(i<10)return 0;i-=10;if(i<6)return radians*i;if(i>14)return radians*(5-(i-15));return radians*5;}
 public static float translation(ItemStack stack){float i=animation(stack);if(i<10)return 0;i-=10;if(i>4&&i<10)return(i-5)*.05F;if(i>9&&i<15)return (10*.05F)-(i-5)*.05F;return 0;}
 @Override public Component getName(ItemStack stack){return Component.translatable("item.gun_b92.name");}
 @Override public void appendHoverText(ItemStack stack,TooltipContext context,List<Component> lines,TooltipFlag flag){if(LegacyStartup.polaroidId==11){lines.add(Component.translatable("tooltip.hbm.b92.fate11.1"));lines.add(Component.translatable("tooltip.hbm.b92.fate11.2"));}else if(LegacyStartup.polaroidId==18){lines.add(Component.translatable("tooltip.hbm.b92.fate18.1"));lines.add(Component.translatable("tooltip.hbm.b92.fate18.2"));}else lines.add(Component.translatable("tooltip.hbm.b92.fateother"));lines.add(Component.empty());for(int i=1;i<=6;i++)lines.add(Component.translatable("tooltip.hbm.b92.info."+i));lines.add(Component.empty());lines.add(Component.translatable("tooltip.hbm.b92.motto"));lines.add(Component.empty());lines.add(Component.translatable("tooltip.hbm.b92.legendary"));}
}
